  await page.goto('http://127.0.0.1:4173/', { waitUntil: 'networkidle' });
  const info = await page.evaluate(async () => {
    await document.fonts.ready;
    const h1 = document.querySelector('h1');
    const cs = getComputedStyle(h1);
    const loaded = [...document.fonts].map(f => ({family:f.family, weight:f.weight, status:f.status, style:f.style}));
    // measure text width with the declared font vs fallbacks
    const measure = (font) => {
      const c = document.createElement('canvas').getContext('2d');
      c.font = font; return c.measureText('Small things that make a').width;
    };
    return {
      fonts: loaded,
      check400: document.fonts.check('400 16px "Acme Sans"'),
      check800: document.fonts.check('800 36px "Acme Sans"'),
      h1: {family: cs.fontFamily, weight: cs.fontWeight, size: cs.fontSize, text: h1.textContent.trim(), rect: h1.getBoundingClientRect().toJSON()},
      widthAcme400: measure('400 36px "Acme Sans"'),
      widthAcme800: measure('800 36px "Acme Sans"'),
      widthFallback: measure('400 36px system-ui'),
      widthDejaVu: measure('400 36px "DejaVu Sans"'),
      widthLiberation: measure('400 36px "Liberation Sans"'),
    };
  });
  console.log(JSON.stringify({resp, info}, null, 1));
  await browser.close();
})();
